      $('#modalForm').addEventListener('input',persistDocumentDraft,true);$('#modalForm').addEventListener('change',persistDocumentDraft,true);lines.addEventListener('click',e=>{if(e.target.closest('.line-remove'))persistDocumentDraft();});
