    bindDocuments(posted);on('#opDirectDte',()=>directDteModal());on('#opBillingPrintFormats',()=>A.navigate('print-formats'));on('#opBillingConfig',()=>A.billingConfigModal(c));on('#opBillingCreds',()=>A.billingCredentialsModal(c));on('#opBillingTest',()=>A.billingTestModal(c));
