      const id=fd.get('document_id');if(!id)throw new Error('Selecciona un documento');await recipientLoad;if($('#opSourceDocument').value!==id)throw new Error('El documento cambió. Revisa el receptor antes de emitir.');const result=await issueConfigured(id,t,format,$('#opDirectPhone').value);return {toast:result.document?.status==='EMITIDO'?`DTE emitido · folio ${result.document?.folio||''}`:'Documento procesado'};
