      recipientLoad=id?window.SiasDtePdf.recipient({document_id:id}).then(r=>{if(sequence!==recipientSequence||!input.isConnected)return;input.value=r.phone||'';input.disabled=false;status.textContent=r.phone?'Se enviará con este documento.':'Puedes agregar un teléfono para esta emisión.';}):Promise.resolve();
