    if(d.status!=='POSTED')throw new Error('Confirma el documento antes de emitir');
    const refs=(r.dte||[]).filter(x=>x.status==='EMITIDO'&&[33,34,39,41,52].includes(Number(x.document_type)));
    const types=d.document_type==='DELIVERY'?[52]:[33,34,39,41,52,56,61];
    if(d.document_type==='DELIVERY')defaultType=52;
    else if(!defaultType){const key=d.document_type==='WHOLESALE'?'WHOLESALE':'SALE';defaultType=Number(formats.issuance?.[key]||33);}
    if(!types.includes(Number(defaultType)))defaultType=types[0];
